// Narrated audience export from a completed, hash-verified run.
//
// Builds one MP4 (single export profile) and one WebVTT per audience from
// recorded run evidence only: the real browser session video, recorded process
// output, catalog-backed diagram cards and Piper narration of storyboard text
// whose claims the claim ledger marks supported. A browser scene whose
// approved run-local helper reported media (for example a simulated user's
// generated voice) becomes an interaction clip after a narrated intro: the
// media play at the times the helper reported, labelled with their approved
// provenance, never under narration. Nothing is re-executed and no
// network is used; cards are rendered by the pinned Chromium with every
// request blocked. The result is structurally checked (probe, frame
// arithmetic, faststart, narration-present/silence windows decoded back) and
// is NOT a release: release needs an independent full-file audiovisual review.
import fs from "node:fs";
import path from "node:path";
import { frameLevels, readWav, writeWav } from "./audio.mjs";
import { launchBrowser } from "./browser.mjs";
import { activeFraction, decodeMono, EXPORT_PROFILE, ffmpegRun, moovBeforeMdat, probeMedia, profileMismatches } from "./export-check.mjs";
import { contentSha256 } from "./canonical.mjs";
import { validateContract } from "./contracts.mjs";
import { readEvents } from "./events.mjs";
import { readJsonFile } from "./io.mjs";
import { verifyManifestFiles } from "./manifest.mjs";
import { synthesizeNarration, toWebVtt } from "./narration.mjs";
import { currentCancellation, ProcRegistry, throwIfCancelled } from "./proc-registry.mjs";
import { sha256File } from "./toolchain.mjs";

export const TIMING = Object.freeze({
	fps: EXPORT_PROFILE.fps,
	titleMs: 4000,
	closingMs: 7000,
	diagramMinMs: 5000,
	panelMinMs: 4000,
	leadMs: 500,
	tailMs: 800,
	clipLeadMs: 300,
	clipTailMs: 700,
	interactionTailMs: 600,
});

const PROFILE_LABEL = Object.freeze({
	video: "h264 High yuv420p 1280x720 30fps crf20 medium",
	audio: "aac LC 48000Hz stereo 160k narrator -16LUFS",
	container: "mp4 +faststart",
});

const NARRATOR_ROLE = "Narrator (generated voice)";
const INTERACTION_AUDIO_LABEL = "aac LC 48000Hz stereo 160k narrator -16LUFS + run-local helper media -16LUFS";
// Helper media must be audible for at least this share of its reported span.
const MIN_MEDIA_ACTIVE = 0.1;
const MIX_RATE = 48000;
/** Default narrator label; a demo plan may rename it. */
export const DEFAULT_VOICES = Object.freeze({ narrator: NARRATOR_ROLE });
/** Caption suffix per approved provenance: helper media are never presented as the app's own output. */
export const PROVENANCE_NOTE = Object.freeze({
	generated: "(generated by the run-local helper, not the app)",
	"helper-captured": "(recorded by the run-local helper; source not verified)",
});
const SILENCE_MARGIN_MS = 250;
const MIN_SILENT_WINDOW_MS = 600;
const MIN_CUE_ACTIVE = 0.5;

const framesOf = (ms) => Math.ceil((ms * TIMING.fps) / 1000);
const msOfFrames = (frames) => (frames * 1000) / TIMING.fps;

/**
 * Lays out the edit: title card, then per scene an optional diagram card and
 * its main visual (recorded-output panel or browser clip), then a closing card.
 * A scene lasts at least its visuals and at least its narration plus lead and
 * tail; extra time is held on the main visual (a clip freezes its last frame).
 *
 * An interaction scene is a narrated still of its first frame (the narration
 * plays only there) followed by the recorded clip with the helper's media and
 * a short held tail; narration never overlaps the interaction.
 *
 * @param {{id: string, diagram: boolean, kind: "recorded-output-panel"|"browser-clip"|"interaction", clipMs?: number, narrationMs: number}[]} scenes
 * @returns {{segments: object[], narrationStartMs: Record<string, number>, interactionStartMs: Record<string, number>, totalFrames: number}}
 */
export function layoutTimeline(scenes) {
	const segments = [];
	const narrationStartMs = {};
	const interactionStartMs = {};
	let cursor = 0;
	const push = (segment) => {
		segments.push({ ...segment, startFrame: cursor });
		cursor += segment.frames;
	};
	push({ id: "seg.title", kind: "title-card", frames: framesOf(TIMING.titleMs) });
	for (const scene of scenes) {
		const sceneStart = cursor;
		if (scene.kind === "interaction") {
			if (scene.diagram) {
				push({ id: `seg.${scene.id}.diagram`, kind: "diagram-card", sceneId: scene.id, frames: framesOf(TIMING.diagramMinMs) });
			}
			narrationStartMs[scene.id] = msOfFrames(cursor) + TIMING.leadMs;
			push({ id: `seg.${scene.id}.intro`, kind: "narrated-still", sceneId: scene.id, frames: framesOf(TIMING.leadMs + scene.narrationMs + TIMING.tailMs) });
			const clipFrames = Math.max(1, framesOf(scene.clipMs));
			const tailFrames = framesOf(TIMING.interactionTailMs);
			interactionStartMs[scene.id] = msOfFrames(cursor);
			push({ id: `seg.${scene.id}.interaction`, kind: "interaction-clip", sceneId: scene.id, frames: clipFrames + tailFrames, clipFrames, heldFrames: tailFrames });
			continue;
		}
		const diagramFrames = scene.diagram ? framesOf(TIMING.diagramMinMs) : 0;
		const clipFrames = scene.kind === "browser-clip" ? Math.max(1, framesOf(scene.clipMs)) : 0;
		const mainMin = scene.kind === "browser-clip" ? clipFrames : framesOf(TIMING.panelMinMs);
		const needed = framesOf(TIMING.leadMs + scene.narrationMs + TIMING.tailMs);
		const total = Math.max(diagramFrames + mainMin, needed);
		if (scene.diagram) {
			push({ id: `seg.${scene.id}.diagram`, kind: "diagram-card", sceneId: scene.id, frames: diagramFrames });
		}
		const mainFrames = total - diagramFrames;
		push({
			id: `seg.${scene.id}.main`,
			kind: scene.kind,
			sceneId: scene.id,
			frames: mainFrames,
			...(scene.kind === "browser-clip" ? { clipFrames, heldFrames: mainFrames - clipFrames } : {}),
		});
		narrationStartMs[scene.id] = msOfFrames(sceneStart) + TIMING.leadMs;
	}
	push({ id: "seg.closing", kind: "closing-card", frames: framesOf(TIMING.closingMs) });
	return { segments, narrationStartMs, interactionStartMs, totalFrames: cursor };
}

/**
 * Windows that must be silent: everything outside the narrated spans, shrunk
 * by a margin on each side, keeping only windows long enough to measure.
 *
 * @param {{startMs: number, endMs: number}[]} spans
 * @param {number} totalMs
 */
export function silentWindows(spans, totalMs) {
	const sorted = [...spans].sort((a, b) => a.startMs - b.startMs);
	const windows = [];
	let from = 0;
	for (const span of sorted) {
		windows.push({ startMs: from + (from === 0 ? 0 : SILENCE_MARGIN_MS), endMs: span.startMs - SILENCE_MARGIN_MS });
		from = Math.max(from, span.endMs);
	}
	windows.push({ startMs: from + SILENCE_MARGIN_MS, endMs: totalMs - 50 });
	return windows.filter((window) => window.endMs - window.startMs >= MIN_SILENT_WINDOW_MS);
}

/**
 * The recorded browser-video window of a scene, from its successful attempts.
 * The lead and tail are clamped to other scenes' timed attempts, so a clip
 * (and its held last frame) never shows the next scene's navigation.
 */
export function clipWindow(events, sceneId) {
	const timed = events.filter((event) => event.type === "action.attempt" && Number.isFinite(event.data?.videoStartMs) && Number.isFinite(event.data?.videoEndMs));
	const attempts = timed.filter((event) => event.sceneId === sceneId && event.disposition === "ok");
	if (attempts.length === 0) {
		return null;
	}
	const start = Math.min(...attempts.map((event) => event.data.videoStartMs));
	const end = Math.max(...attempts.map((event) => event.data.videoEndMs));
	const others = timed.filter((event) => event.sceneId !== sceneId);
	const previousEnd = Math.max(0, ...others.filter((event) => event.data.videoEndMs <= start).map((event) => event.data.videoEndMs));
	const nextStart = Math.min(Infinity, ...others.filter((event) => event.data.videoStartMs >= end).map((event) => event.data.videoStartMs));
	return { inMs: Math.max(previousEnd, start - TIMING.clipLeadMs), outMs: Math.min(nextStart, end + TIMING.clipTailMs) };
}

/**
 * The recorded window of an interaction scene: its clip window, starting
 * after an opening navigation (a blank page loading is not part of it).
 */
export function interactionWindow(events, scene) {
	const clip = clipWindow(events, scene.id);
	if (!clip) {
		return null;
	}
	const first = scene.actions[0];
	if (first?.op === "goto") {
		const opened = events.find((event) => event.type === "action.attempt" && event.actionId === first.id && event.disposition === "ok");
		if (opened && Number.isFinite(opened.data?.videoEndMs) && opened.data.videoEndMs < clip.outMs) {
			return { inMs: Math.max(clip.inMs, opened.data.videoEndMs), outMs: clip.outMs };
		}
	}
	return clip;
}

/**
 * Media reported by the successful helper actions of a scene, from their
 * recorded helper results. Every media artifact must be recorded in the run
 * manifest with the same sha256.
 *
 * @returns {{media: object[], problems: string[]}}
 */
export function sceneHelperMedia({ runPath, events, scene, recorded }) {
	const media = [];
	const problems = [];
	const helperActions = new Set(scene.actions.filter((action) => action.op === "helper").map((action) => action.id));
	const attempts = events.filter((event) => event.type === "action.attempt" && event.sceneId === scene.id && event.disposition === "ok" && helperActions.has(event.actionId));
	for (const attempt of attempts) {
		const ref = attempt.evidenceRef;
		if (!ref || !recorded.has(ref)) {
			problems.push(`helper action ${attempt.actionId} has no recorded helper result`);
			continue;
		}
		let result;
		try {
			result = readJsonFile(path.join(runPath, ref), "helper result");
		} catch (error) {
			problems.push(`helper action ${attempt.actionId}: ${error.message}`);
			continue;
		}
		for (const item of Array.isArray(result.media) ? result.media : []) {
			const artifact = recorded.get(item.artifact);
			if (!artifact || artifact.role !== "helper-media" || artifact.sha256 !== item.sha256) {
				problems.push(`helper action ${attempt.actionId} names media ${String(item.artifact).slice(0, 200)} that the run manifest does not record as helper-media with that sha256`);
				continue;
			}
			if (!["generated", "helper-captured"].includes(item.provenance) || !Number.isFinite(item.videoStartMs) || !Number.isFinite(item.durationMs)) {
				problems.push(`helper action ${attempt.actionId} media ${item.artifact} has no valid provenance or timing`);
				continue;
			}
			media.push({ actionId: attempt.actionId, ...item });
		}
	}
	return { media, problems };
}

/**
 * Everything that must hold before an export is attempted. Returns blocking
 * reasons (empty when producible) and the loaded, verified inputs.
 */
export function checkProducible({ runPath, calibrationFile, audience }) {
	const reasons = [];
	const read = (file, label) => {
		try {
			return readJsonFile(file, label);
		} catch (error) {
			reasons.push(`${label}: ${error.message}`);
			return null;
		}
	};
	const calibration = read(calibrationFile, "calibration");
	if (calibration) {
		if (calibration.passed !== true) {
			reasons.push("the calibration did not pass");
		}
		if (contentSha256(calibration.export?.profile ?? null) !== contentSha256(EXPORT_PROFILE)) {
			reasons.push("the calibration was made with a different export profile");
		}
		if (!Number.isFinite(calibration.floors?.exportThresholdDb)) {
			reasons.push("the calibration has no export silence threshold");
		}
	}
	const manifest = read(path.join(runPath, "manifest.json"), "manifest");
	const qa = read(path.join(runPath, "qa-report.json"), "qa report (run `sdp qa` first)");
	const ledger = read(path.join(runPath, "claim-ledger.json"), "claim ledger (run `sdp qa` first)");
	if (!manifest || !qa || !ledger) {
		return { reasons };
	}
	const manifestErrors = validateContract("artifact-manifest", manifest);
	if (manifestErrors.length) {
		reasons.push("the run manifest is not a valid artifact-manifest.v1");
		return { reasons };
	}
	const failedFiles = verifyManifestFiles(runPath, manifest).filter((check) => check.status !== "pass");
	if (failedFiles.length) {
		reasons.push(`run artifacts failed verification: ${failedFiles.map((check) => check.id).join(", ")}`);
	}
	if (manifest.status !== "completed") {
		reasons.push(`the run status is ${manifest.status}, not completed`);
	}
	const manifestSha256 = contentSha256(manifest);
	if (validateContract("qa-report", qa).length || validateContract("claim-ledger", ledger).length) {
		reasons.push("the QA report or claim ledger is not a valid contract");
	} else {
		if (qa.manifestSha256 !== manifestSha256 || ledger.manifestSha256 !== manifestSha256) {
			reasons.push("the QA report or claim ledger was made for a different manifest");
		}
		if (qa.claimLedgerSha256 !== contentSha256(ledger)) {
			reasons.push("the QA report does not match the claim ledger");
		}
		const open = qa.checks.filter((check) => check.status !== "pass" && check.id !== "audiovisual-export");
		if (qa.verdict === "fail" || open.length) {
			reasons.push(`structural QA has open checks: ${open.map((check) => `${check.id}=${check.status}`).join(", ") || qa.verdict}`);
		}
	}
	const recorded = new Map(manifest.artifacts.map((artifact) => [artifact.path, artifact]));
	const storyboard = read(path.join(runPath, "contracts", "storyboard.json"), "recorded storyboard");
	const catalog = read(path.join(runPath, "contracts", "catalog.json"), "recorded catalog");
	const authorization = read(path.join(runPath, "contracts", "authorization.json"), "recorded authorization");
	for (const name of ["contracts/storyboard.json", "contracts/catalog.json", "contracts/authorization.json", "events.jsonl"]) {
		if (!recorded.has(name)) {
			reasons.push(`the manifest does not record ${name}`);
		}
	}
	if (!storyboard || !catalog || !authorization || reasons.length) {
		return { reasons };
	}
	if (!storyboard.audiences.includes(audience)) {
		reasons.push(`the storyboard has no ${audience} audience (has ${storyboard.audiences.join(", ")})`);
	}
	const verdicts = new Map(ledger.claims.map((claim) => [claim.id, claim.verdict]));
	const events = readEvents(path.join(runPath, "events.jsonl"));
	for (const scene of storyboard.scenes) {
		const narration = scene.narration.filter((entry) => entry.audience === audience);
		if (narration.length !== 1) {
			reasons.push(`scene ${scene.id} has ${narration.length} ${audience} narration entries; exactly one is needed`);
			continue;
		}
		for (const claim of narration[0].claims) {
			if (verdicts.get(claim) !== "supported") {
				reasons.push(`narration ${narration[0].id} asserts ${claim}, which the claim ledger marks ${verdicts.get(claim) ?? "absent"}`);
			}
		}
		if (scene.adapter === "browser") {
			if (!recorded.has("browser/session.webm")) {
				reasons.push(`scene ${scene.id} needs the recorded browser video`);
			}
			if (!clipWindow(events, scene.id)) {
				reasons.push(`scene ${scene.id} has no timed successful browser actions`);
			}
			reasons.push(...sceneHelperMedia({ runPath, events, scene, recorded }).problems.map((problem) => `scene ${scene.id}: ${problem}`));
		} else if (scene.adapter !== "process" && scene.adapter !== "http") {
			reasons.push(`scene ${scene.id} uses the ${scene.adapter} adapter, which has no export visual`);
		}
	}
	return {
		reasons,
		inputs: { calibration, manifest, manifestSha256, qa, ledger, storyboard, catalog, authorization, events, recorded },
	};
}

export const escapeHtml = (text) => String(text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

