export function cardHtml({ badge, body, footer }) {
	return `<!doctype html><html><head><meta charset="utf-8"><style>${CARD_CSS}</style></head><body><div class="badge">${escapeHtml(badge)}</div>${body}<div class="footer">${escapeHtml(footer)}</div></body></html>`;
}

function evidenceLabel(catalog, id) {
	const item = catalog.evidence.find((entry) => entry.id === id);
	if (!item) {
		return id;
	}
	const lines = item.ref?.lines ? `:${item.ref.lines.start}-${item.ref.lines.end}` : "";
	return `${item.ref?.path ?? id}${lines}`;
}

function componentNode(catalog, id) {
	const component = catalog.components.find((entry) => entry.id === id);
	return `<div class="node">${escapeHtml(component?.name ?? id)}<small>${escapeHtml(component?.kind ?? "")}</small></div>`;
}

function diagramBody(catalog, scene) {
	const edges = scene.diagram.edges.map((id) => catalog.edges.find((edge) => edge.id === id));
	const chain = edges.every((edge, index) => index === 0 || edges[index - 1].to === edge.from);
	const arrow = (edge) => `<div class="arrow"><b>&rarr;</b>${escapeHtml(edge.label ?? "")}</div>`;
	const graph = chain
		? `<div class="flow">${componentNode(catalog, edges[0].from)}${edges.map((edge) => `${arrow(edge)}${componentNode(catalog, edge.to)}`).join("")}</div>`
		: `<div class="rows">${edges.map((edge) => `<div class="row">${componentNode(catalog, edge.from)}${arrow(edge)}${componentNode(catalog, edge.to)}</div>`).join("")}</div>`;
	const classes = [...new Set(edges.map((edge) => edge.class))].join(", ");
	const evidence = [...new Set(edges.flatMap((edge) => edge.evidence))].map((id) => evidenceLabel(catalog, id));
	return `<h2>${escapeHtml(scene.diagram.caption)}</h2>${graph}<p class="evidence">Edge class: ${escapeHtml(classes)}. Evidence (hashed in the catalog): ${escapeHtml(evidence.join(", "))}</p>`;
}

function readCapped(file, maxLines = 14, maxChars = 1400) {
	if (!file || !fs.existsSync(file)) {
		return "";
	}
	const text = fs.readFileSync(file, "utf8");
	const lines = text.split("\n");
	let shown = lines.slice(0, maxLines).join("\n");
	if (shown.length > maxChars) {
		shown = shown.slice(0, maxChars);
	}
	return shown.length < text.trimEnd().length ? `${shown.trimEnd()}\n[... truncated for display]` : shown.trimEnd();
}

export function panelBody({ runPath, scene, authorization, events }) {
	if (scene.adapter === "http") {
		return httpPanelBody({ runPath, scene, authorization, events });
	}
	const blocks = [];
	for (const action of scene.actions) {
		const attempt = events.filter((event) => event.type === "action.attempt" && event.actionId === action.id).at(-1);
		const command = authorization.commands.find((entry) => entry.id === action.ref);
		const argv = command ? [command.executable, ...command.argv].join(" ") : action.ref;
		const stdoutFile = attempt?.evidenceRef ? path.join(runPath, attempt.evidenceRef) : null;
		const stderrFile = stdoutFile?.endsWith(".stdout") ? stdoutFile.replace(/\.stdout$/, ".stderr") : null;
		const stdout = readCapped(stdoutFile);
		const stderr = readCapped(stderrFile);
		blocks.push(
			[
				`<span class="cmd">$ ${escapeHtml(argv)}</span>`,
				stdout ? escapeHtml(stdout) : "",
				stderr ? `<span class="err">${escapeHtml(stderr)}</span>` : "",
				`<span class="exit">[exit code ${escapeHtml(attempt?.data?.exitCode ?? "unknown")}]</span>`,
			]
				.filter(Boolean)
				.join("\n"),
		);
	}
	return `<h2>${escapeHtml(scene.title)}</h2><pre>${blocks.join("\n\n")}</pre><p class="muted" style="font-size:18px;margin-top:14px">Recorded output of the real command in this run, shown as text: not a live terminal. {workspace} is the run's private output folder.</p>`;
}

/** Recorded request lines, statuses and response bodies of an HTTP scene. Request headers are never shown. */
function httpPanelBody({ runPath, scene, authorization, events }) {
	const blocks = [];
	for (const action of scene.actions) {
		const attempt = events.filter((event) => event.type === "action.attempt" && event.actionId === action.id).at(-1);
		const request = authorization.http.requests.find((entry) => entry.id === action.ref);
		const line = request ? `${request.method} ${request.path}` : action.ref;
		const body = readCapped(attempt?.evidenceRef ? path.join(runPath, attempt.evidenceRef) : null);
		blocks.push(
			[
				`<span class="cmd">&gt; ${escapeHtml(line)}</span>`,
				`<span class="exit">[HTTP ${escapeHtml(attempt?.data?.status ?? "no response")}]</span>`,
				body ? escapeHtml(body) : "",
			]
				.filter(Boolean)
				.join("\n"),
		);
	}
	return `<h2>${escapeHtml(scene.title)}</h2><pre>${blocks.join("\n\n")}</pre><p class="muted" style="font-size:18px;margin-top:14px">Recorded requests and responses from this run, shown as text: not a live API console.</p>`;
}

function claimBasis(claim, catalog) {
	const runRefs = claim.evidence.filter((item) => item.type === "run-action").map((item) => item.ref);
	const sources = claim.evidence.filter((item) => item.type === "catalog-evidence").map((item) => evidenceLabel(catalog, item.ref));
	if (runRefs.length) {
		return `observed in this run (${runRefs.join(", ")})`;
	}
	return `${claim.class} (${sources.join(", ")})`;
}

/**
 * Produces one audience export into outDir. Returns the export manifest; the
 * caller maps verdict to an exit code.
 * voices: the narrator's on-screen and caption label.
 */
export async function produce({ runPath, calibrationFile, audience, outDir, paths, voices = DEFAULT_VOICES, log = () => {} }) {
	const { reasons, inputs } = checkProducible({ runPath, calibrationFile, audience });
	if (reasons.length) {
		return { blocked: reasons };
	}
	const { calibration, manifest, manifestSha256, qa, ledger, storyboard, catalog, authorization, events, recorded } = inputs;
	const dirs = Object.fromEntries(["audio", "cards", "final", "qa", "work"].map((name) => [name, path.join(outDir, name)]));
	for (const dir of Object.values(dirs)) {
		fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
	}
	const env = {
		PATH: "/usr/bin:/bin",
		HOME: outDir,
		TMPDIR: dirs.work,
		XDG_CACHE_HOME: path.join(dirs.work, ".cache"),
		PYTHONDONTWRITEBYTECODE: "1",
		LANG: "C.UTF-8",
	};
	const files = [];
	const addFile = (file, role) => files.push({ path: path.relative(outDir, file), sha256: sha256File(file), bytes: fs.statSync(file).size, role });
	// Each stage starts only while the caller's run deadline and cancellation allow it.
	const stage = (line) => {
		throwIfCancelled();
		log(line);
	};
	try {
		stage(`synthesizing ${audience} narration`);
		const voiced = [];
		for (const scene of storyboard.scenes) {
			const entry = scene.narration.find((item) => item.audience === audience);
			const wav = path.join(dirs.audio, `${scene.id}.wav`);
			const voice = await synthesizeNarration({ text: entry.text, outWav: wav, paths, role: voices.narrator });
			addFile(wav, "narration-audio");
			voiced.push({ scene, entry, wav, voice });
		}
		const webm = path.join(runPath, "browser", "session.webm");
		const layoutInput = voiced.map(({ scene, voice }) => {
			const helperMedia = scene.adapter === "browser" ? sceneHelperMedia({ runPath, events, scene, recorded }).media : [];
			if (helperMedia.length) {
				const clip = interactionWindow(events, scene);
				return { id: scene.id, diagram: Boolean(scene.diagram), kind: "interaction", clipMs: clip.outMs - clip.inMs, clip, media: helperMedia, narrationMs: voice.durationMs };
			}
			const clip = scene.adapter === "browser" ? clipWindow(events, scene.id) : null;
			return {
				id: scene.id,
				diagram: Boolean(scene.diagram),
				kind: clip ? "browser-clip" : "recorded-output-panel",
				...(clip ? { clipMs: clip.outMs - clip.inMs, clip } : {}),
				narrationMs: voice.durationMs,
			};
		});
		const layout = layoutTimeline(layoutInput);
		const totalMs = msOfFrames(layout.totalFrames);

		stage("rendering cards with the pinned browser (all requests blocked)");
		const synthetic = storyboard.confidentiality.onScreen === "synthetic-only";
		const interactionItems = layoutInput.filter((item) => item.kind === "interaction");
		const mediaLabels = [...new Map(interactionItems.flatMap((item) => item.media).map((item) => [`${item.label}|${item.provenance}`, item])).values()];
		const footer = `${synthetic ? "Synthetic data only" : "Approved repository content"} - recorded run ${manifest.runId} - ${audience} cut - generated narration`;
		const subjectText = authorization.subject === "synthetic-fixture" ? "the bundled synthetic test fixture" : "the app";
		const voicesText = mediaLabels.length
			? `<p class="muted"><b>${escapeHtml(voices.narrator)}</b> explains. Other audio comes from this demo's run-local helper: ${mediaLabels.map((item) => `<b>${escapeHtml(item.label)}</b> ${escapeHtml(PROVENANCE_NOTE[item.provenance])}`).join("; ")}.</p>`
			: `<p class="muted">The narrator is a generated voice; it states only claims the run's claim ledger marks supported.</p>`;
		const cardFiles = {};
		const registry = new ProcRegistry({ logFile: path.join(outDir, "processes.jsonl") });
		const browser = await launchBrowser({ paths, dir: outDir, registry, origins: [], recordVideo: false, id: "card-browser", signal: currentCancellation() });
		try {
			const page = await browser.context.newPage();
			const render = async (id, html) => {
				throwIfCancelled();
				await page.setContent(html, { waitUntil: "load" });
				const file = path.join(dirs.cards, `${id}.png`);
				await page.screenshot({ path: file, fullPage: false });
				addFile(file, "card-image");
				cardFiles[id] = file;
			};
			await render(
				"seg.title",
				cardHtml({
					badge: `${audience} audience`,
					body: `<h1>${escapeHtml(storyboard.title)}</h1><p>${escapeHtml(storyboard.goal)}</p><p class="muted">Everything shown was recorded from a real local run of ${escapeHtml(subjectText)}. The narrator states only claims the run's claim ledger marks supported.</p>${voicesText}`,
					footer,
				}),
			);
			for (const segment of layout.segments) {
				const scene = storyboard.scenes.find((item) => item.id === segment.sceneId);
				if (segment.kind === "diagram-card") {
					await render(segment.id, cardHtml({ badge: "diagram from catalog evidence", body: diagramBody(catalog, scene), footer }));
				} else if (segment.kind === "recorded-output-panel") {
					await render(segment.id, cardHtml({ badge: "recorded output", body: panelBody({ runPath, scene, authorization, events }), footer }));
				}
			}
			const narrated = new Set(voiced.flatMap(({ entry }) => entry.claims));
			const claims = ledger.claims.filter((claim) => narrated.has(claim.id));
			const claimText = new Map(storyboard.claims.map((claim) => [claim.id, claim.text]));
			await render(
				"seg.closing",
				cardHtml({
					badge: "claims and evidence",
					body: `<h2>What this demo showed</h2><ul>${claims.map((claim) => `<li>${escapeHtml(claimText.get(claim.id) ?? claim.id)} <span class="muted">- <span class="v">${escapeHtml(claim.verdict)}</span>, ${escapeHtml(claimBasis(claim, catalog))}</span></li>`).join("")}</ul><p class="muted" style="font-size:16px;margin-top:10px">Run manifest ${manifestSha256.slice(0, 16)}: every structural run check passed. This export is not released until an independent full-file watch-and-listen review.</p>`,
					footer,
				}),
			);
			await page.close();
		} finally {
			const closed = await browser.close();
			if (closed.stopped.result === "failed" || registry.survivors().length) {
				throw new Error("the card browser did not exit cleanly");
			}
		}

		stage("assembling the narration track");
		const sampleRate = voiced[0].voice.sampleRate;
		const track = new Float32Array(Math.round((totalMs / 1000) * sampleRate));
		const narration = [];
		const cues = [];
		for (const { scene, entry, wav, voice } of voiced) {
			const startMs = layout.narrationStartMs[scene.id];
			const samples = readWav(wav).samples;
			track.set(samples, Math.round((startMs / 1000) * sampleRate));
			narration.push({ sceneId: scene.id, narrationId: entry.id, claims: entry.claims, startMs, endMs: startMs + voice.durationMs, audio: path.relative(outDir, wav) });
			cues.push(...voice.cues.map((cue) => ({ ...cue, startMs: cue.startMs + startMs, endMs: cue.endMs + startMs })));
		}
		const trackWav = path.join(dirs.work, "narration-track.wav");
		writeWav(trackWav, track, sampleRate);

		const interactionClips = [];
		// Each placed media file's own levels: the export check needs them because
		// the mix can make a silent file look audible when another file overlaps it.
		const sourceLevels = new WeakMap();
		let mediaWav = null;
		if (interactionItems.length) {
			stage("placing the run-local helper media");
			const mix = new Float32Array(Math.round((totalMs / 1000) * MIX_RATE));
			for (const item of interactionItems) {
				const { clip } = item;
				const atMs = layout.interactionStartMs[item.id];
				const clipEndMs = atMs + item.clipMs;
				const toExport = (videoMs) => atMs + (videoMs - clip.inMs);
				const placed = [];
				for (const media of item.media) {
					const wav = readWav(path.join(runPath, media.artifact));
					const samples = resampleLinear(wav.samples, wav.sampleRate, MIX_RATE);
					const startMs = toExport(media.videoStartMs);
					const from = Math.round((startMs / 1000) * MIX_RATE);
					const stop = Math.min(mix.length, Math.round((clipEndMs / 1000) * MIX_RATE));
					for (let index = 0; index < samples.length; index += 1) {
						const at = from + index;
						if (at >= 0 && at < stop) {
							mix[at] += samples[index];
						}
					}
					const span = { startMs: Math.max(atMs, startMs), endMs: Math.min(clipEndMs, startMs + media.durationMs) };
					if (span.endMs <= span.startMs) {
						continue;
					}
					cues.push({ role: media.label, text: `${media.caption ?? "[audio]"} ${PROVENANCE_NOTE[media.provenance]}`, ...span, source: "helper" });
					const entry = { actionId: media.actionId, role: media.role, label: media.label, provenance: media.provenance, timingSource: "helper-reported", artifact: media.artifact, sha256: media.sha256, ...span };
					sourceLevels.set(entry, { frames: frameLevels(samples, MIX_RATE, 10), offsetMs: startMs });
					placed.push(entry);
				}
				if (placed.length) {
					interactionClips.push({ sceneId: item.id, startMs: atMs, endMs: clipEndMs, inMs: clip.inMs, outMs: clip.outMs, media: placed });
				}
			}
			mediaWav = path.join(dirs.work, "helper-media-track.wav");
			writeWav(mediaWav, mix, MIX_RATE);
		}

		stage("encoding the export");
		const inputs_ = [];
		const filters = [];
		const segments = [];
		for (const [index, segment] of layout.segments.entries()) {
			const scale = `fps=${TIMING.fps},scale=${EXPORT_PROFILE.width}:${EXPORT_PROFILE.height}:flags=bicubic,format=${EXPORT_PROFILE.pixFmt},setsar=1`;
			const label = segment.kind === "browser-clip" ? `recorded browser session ${segment.sceneId}` : `${segment.kind} ${segment.sceneId ?? ""}`.trim();
			if (segment.kind === "narrated-still") {
				const { clip } = layoutInput.find((item) => item.id === segment.sceneId);
				inputs_.push("-i", webm);
				filters.push(`[${index}:v]trim=start=${(clip.inMs / 1000).toFixed(3)}:end=${((clip.inMs + 200) / 1000).toFixed(3)},setpts=PTS-STARTPTS,${scale},trim=end_frame=1,tpad=stop_mode=clone:stop=-1,trim=end_frame=${segment.frames},setpts=PTS-STARTPTS[v${index}]`);
				segments.push({ id: segment.id, kind: segment.kind, sceneId: segment.sceneId, startFrame: segment.startFrame, frames: segment.frames, label: `narrated still of ${segment.sceneId}`, source: { artifact: "browser/session.webm", sha256: recorded.get("browser/session.webm").sha256, inMs: clip.inMs, outMs: clip.inMs, heldFrames: segment.frames - 1 } });
			} else if (segment.kind === "browser-clip" || segment.kind === "interaction-clip") {
				const { clip } = layoutInput.find((item) => item.id === segment.sceneId);
				inputs_.push("-i", webm);
				filters.push(`[${index}:v]trim=start=${(clip.inMs / 1000).toFixed(3)}:end=${(clip.outMs / 1000).toFixed(3)},setpts=PTS-STARTPTS,${scale},tpad=stop_mode=clone:stop=-1,trim=end_frame=${segment.frames},setpts=PTS-STARTPTS[v${index}]`);
				segments.push({ id: segment.id, kind: segment.kind, sceneId: segment.sceneId, startFrame: segment.startFrame, frames: segment.frames, label, source: { artifact: "browser/session.webm", sha256: recorded.get("browser/session.webm").sha256, inMs: clip.inMs, outMs: clip.outMs, heldFrames: segment.heldFrames } });
			} else {
				const card = cardFiles[segment.id];
				inputs_.push("-loop", "1", "-framerate", String(TIMING.fps), "-i", card);
				filters.push(`[${index}:v]${scale},trim=end_frame=${segment.frames},setpts=PTS-STARTPTS[v${index}]`);
				segments.push({ id: segment.id, kind: segment.kind, ...(segment.sceneId ? { sceneId: segment.sceneId } : {}), startFrame: segment.startFrame, frames: segment.frames, label, source: { artifact: path.relative(outDir, card), sha256: sha256File(card) } });
			}
		}
		const audioIndex = layout.segments.length;
		inputs_.push("-i", trackWav);
		filters.push(`${layout.segments.map((_, index) => `[v${index}]`).join("")}concat=n=${layout.segments.length}:v=1:a=0[v]`);
		const end = (totalMs / 1000).toFixed(6);
		if (mediaWav) {
			inputs_.push("-i", mediaWav);
			filters.push(`[${audioIndex}:a]loudnorm=I=${EXPORT_PROFILE.narratorLufs}:TP=-1.5:LRA=11,aresample=${EXPORT_PROFILE.sampleRate},apad,atrim=end=${end}[n]`);
			filters.push(`[${audioIndex + 1}:a]loudnorm=I=${EXPORT_PROFILE.narratorLufs}:TP=-1.5:LRA=11,aresample=${EXPORT_PROFILE.sampleRate},apad,atrim=end=${end}[c]`);
			filters.push(`[n][c]amix=inputs=2:normalize=0:duration=longest,pan=stereo|c0=c0|c1=c0,apad,atrim=end=${end}[a]`);
		} else {
			filters.push(`[${audioIndex}:a]loudnorm=I=${EXPORT_PROFILE.narratorLufs}:TP=-1.5:LRA=11,aresample=${EXPORT_PROFILE.sampleRate},pan=stereo|c0=c0|c1=c0,apad,atrim=end=${end}[a]`);
		}
		const base = `${manifest.runId}-${audience}`;
		const finalMp4 = path.join(dirs.final, `${base}.mp4`);
		await ffmpegRun(paths, [
			...inputs_,
			"-filter_complex", filters.join(";"), "-map", "[v]", "-map", "[a]",
			"-c:v", "libx264", "-profile:v", "high", "-preset", EXPORT_PROFILE.preset, "-crf", String(EXPORT_PROFILE.crf), "-r", String(EXPORT_PROFILE.fps), "-pix_fmt", EXPORT_PROFILE.pixFmt,
			"-c:a", "aac", "-profile:a", "aac_low", "-b:a", EXPORT_PROFILE.audioBitrate, "-ar", String(EXPORT_PROFILE.sampleRate), "-ac", String(EXPORT_PROFILE.channels),
			"-movflags", "+faststart", "-frames:v", String(layout.totalFrames), finalMp4,
		], env);
		cues.sort((a, b) => a.startMs - b.startMs);
		const vttFile = path.join(dirs.final, `${base}.vtt`);
		fs.writeFileSync(vttFile, toWebVtt(cues), { flag: "wx" });

		stage("checking the export");
		const checks = await checkExport({ paths, env, finalMp4, vttFile, cues, narration, interactionClips, sourceLevels, totalFrames: layout.totalFrames, thresholdDb: calibration.floors.exportThresholdDb, work: dirs.work });
		addFile(finalMp4, "export-video");
		addFile(vttFile, "captions");
		const framesDir = path.join(dirs.qa, "frames");
		fs.mkdirSync(framesDir, { recursive: true });
		for (const segment of segments) {
			const atSec = msOfFrames(segment.startFrame + Math.floor(segment.frames / 2)) / 1000;
			const frame = path.join(framesDir, `${segment.id}.png`);
			await ffmpegRun(paths, ["-ss", atSec.toFixed(3), "-i", finalMp4, "-frames:v", "1", frame], env);
			addFile(frame, "review-frame");
		}
		checks.push({ id: "review-frames", status: "pass", detail: `${segments.length} mid-segment frames extracted for visual inspection` });
		const exportManifest = {
			schema: "export-manifest.v1",
			runId: manifest.runId,
			audience,
			inputs: {
				runManifestSha256: manifestSha256,
				qaReportSha256: contentSha256(qa),
				claimLedgerSha256: contentSha256(ledger),
				calibrationSha256: sha256File(calibrationFile),
			},
			profile: { ...PROFILE_LABEL, ...(interactionClips.length ? { audio: INTERACTION_AUDIO_LABEL } : {}) },
			totalFrames: layout.totalFrames,
			durationMs: totalMs,
			segments,
			narration,
			...(interactionClips.length ? { interactionClips } : {}),
			files,
			checks,
			verdict: checks.every((check) => check.status === "pass") ? "structural-pass" : "fail",
			limitations: [
				"Structural checks only: an independent full-file audiovisual review of the exact MP4 is required before release.",
				"Recorded process output and HTTP responses are shown as text panels, not live terminal or API console recordings.",
				"Browser clips are the recorded headless session; a held last frame extends a clip while narration finishes.",
				...(interactionClips.length
					? [
							"Interaction media come from this demo's run-local helper and are placed at the times the helper reported; the run did not measure picture/sound alignment, so check it in the full-file review.",
							"Generated media were made by the helper (never the app's output); helper-captured media are the helper's own recording, whose source the run did not verify. Captions say which.",
							"A helper's success report is its own claim; the run only checked structural evidence (protocol, exit, media files, and that the expected page text newly appeared), not that the app's reply belongs to the helper's action.",
						]
					: []),
			],
		};
		const errors = validateContract("export-manifest", exportManifest);
		if (errors.length) {
			throw new Error(`export manifest is invalid: ${errors.map((error) => `${error.path} ${error.message}`).join("; ")}`);
		}
		fs.writeFileSync(path.join(outDir, "export-manifest.json"), `${JSON.stringify(exportManifest, null, "\t")}\n`, { flag: "wx" });
		return { exportManifest };
	} finally {
		for (const name of ["browser-home", "browser-tmp", "raw-video", "work"]) {
			fs.rmSync(path.join(outDir, name), { recursive: true, force: true });
		}
	}
}

async function checkExport({ paths, env, finalMp4, vttFile, cues, narration, interactionClips = [], sourceLevels = new WeakMap(), totalFrames, thresholdDb, work }) {
	const checks = [];
	const add = (id, pass, detail) => checks.push({ id, status: pass ? "pass" : "fail", detail });
	const probe = await probeMedia(paths, finalMp4, env);
	const mismatches = profileMismatches(probe, totalFrames);
	add("export-profile", mismatches.length === 0, mismatches.length ? `profile mismatches: ${mismatches.join(", ")}` : `matches the single export profile; ${totalFrames} frames as planned`);
	add("faststart", moovBeforeMdat(finalMp4), "moov atom precedes mdat");
	const durationMs = Number(probe.format?.duration) * 1000;
	const plannedMs = msOfFrames(totalFrames);
	add("duration", Math.abs(durationMs - plannedMs) <= 100, `container ${durationMs.toFixed(0)} ms, edit ${plannedMs.toFixed(0)} ms`);
	const decoded = await decodeMono(paths, finalMp4, path.join(work, "export-decoded.wav"), env);
	const frames = frameLevels(decoded.samples, decoded.sampleRate, 10);
	const narratorCues = cues.filter((cue) => cue.source === undefined);
	const quiet = narratorCues.map((cue) => ({ text: cue.text.slice(0, 40), active: activeFraction(frames, cue.startMs + 50, cue.endMs - 50, thresholdDb) })).filter((cue) => cue.active < MIN_CUE_ACTIVE);
	add("narration-audible", quiet.length === 0, quiet.length ? `cues below ${MIN_CUE_ACTIVE} active: ${quiet.map((cue) => `"${cue.text}" ${cue.active.toFixed(2)}`).join("; ")}` : `all ${narratorCues.length} narration caption cues have narration above ${thresholdDb} dB`);
	if (interactionClips.length) {
		const overlaps = narration.filter((span) => interactionClips.some((part) => span.startMs < part.endMs && span.endMs > part.startMs));
		add("narration-media-separated", overlaps.length === 0, overlaps.length ? `narration overlaps an interaction clip: ${overlaps.map((span) => span.narrationId).join(", ")}` : `${narration.length} narration spans and ${interactionClips.length} interaction clip(s) do not overlap`);
		const spans = interactionClips.flatMap((part) => part.media);
		// Both the file's own samples (over its placed span) and the exported mix
		// must be audible; the mix alone cannot tell overlapping files apart.
		const weak = spans
			.map((media) => {
				const own = sourceLevels.get(media);
				const source = own ? activeFraction(own.frames, media.startMs - own.offsetMs, media.endMs - own.offsetMs, thresholdDb) : 0;
				return { media, source, active: activeFraction(frames, media.startMs, media.endMs, thresholdDb) };
			})
			.filter((item) => item.source < MIN_MEDIA_ACTIVE || item.active < MIN_MEDIA_ACTIVE);
		add(
			"helper-media-audible",
			spans.length > 0 && weak.length === 0,
			weak.length
				? `helper media below ${MIN_MEDIA_ACTIVE} active: ${weak.map((item) => `${item.media.role} ${item.media.artifact} at ${item.media.startMs.toFixed(0)} ms: own file ${item.source.toFixed(2)}, export ${item.active.toFixed(2)}`).join("; ")}`
				: `each of ${spans.length} helper media file(s) is audible on its own and in the export`,
		);
	}
	const windows = silentWindows([...narration, ...interactionClips], plannedMs);
	const loud = windows
		.map((window) => ({ ...window, active: activeFraction(frames, window.startMs, window.endMs, thresholdDb) }))
		.filter((window) => window.active > 0);
	add("silence-outside-narration", loud.length === 0, loud.length ? `audio outside narration: ${loud.map((window) => `${window.startMs.toFixed(0)}-${window.endMs.toFixed(0)} ms ${window.active.toFixed(3)}`).join("; ")}` : `${windows.length} windows outside narration${interactionClips.length ? " and interaction clips" : ""} are at digital silence (${thresholdDb} dB)`);
	const vtt = fs.readFileSync(vttFile, "utf8");
	const cueCount = (vtt.match(/ --> /g) ?? []).length;
	const lastEnd = Math.max(...cues.map((cue) => cue.endMs));
	add("captions", cueCount === cues.length && lastEnd <= plannedMs, `${cueCount} cues, last ends ${lastEnd.toFixed(0)} ms of ${plannedMs.toFixed(0)} ms`);
	return checks;
}

/** Linear resampling of mono floats (helper media may use any supported rate). */
export function resampleLinear(samples, fromRate, toRate) {
	if (fromRate === toRate) {
		return samples;
	}
	const length = Math.floor((samples.length * toRate) / fromRate);
	const out = new Float32Array(length);
	for (let index = 0; index < length; index += 1) {
		const position = (index * fromRate) / toRate;
		const left = Math.floor(position);
		const right = Math.min(samples.length - 1, left + 1);
		const fraction = position - left;
		out[index] = samples[left] * (1 - fraction) + samples[right] * fraction;
	}
	return out;
}
